#ifndef NCLGL_NCLGLVERTEXFRAGMENTPROGRAM_H
#define NCLGL_NCLGLVERTEXFRAGMENTPROGRAM_H

#include <string.h>
#include <vector>

#include "NCLGLPgrInValue.h"
#include "NCLGLUtils.h"

class NCLGLVertexFragmentProgram {
    public:
        NCLGLVertexFragmentProgram();
        ~NCLGLVertexFragmentProgram(void);

        void init(std::string *name, std::vector<std::string> arrOutput,
                  uint8_t *drawMode, uint8_t *depthTest, uint8_t *blend,
                  std::string blendEquation, std::string blendSrcMode, std::string blendDstMode,
                  std::string vertexHeader, std::string vertexSource,
                  std::vector<std::string> v_varname, std::vector<std::string> v_varnameC, std::vector<std::string> v_type, std::vector<std::string> v_expectedMode, int v_inValuesCount,
                  std::string fragmentHeader, std::string fragmentSource,
                  std::vector<std::string> f_varname, std::vector<std::string> f_varnameC, std::vector<std::string> f_type, std::vector<std::string> f_expectedMode, int f_inValuesCount);

        std::string _precision;
        std::string version;

        std::string _name;
        bool enabled;
        uint8_t _depthTest;
        uint8_t _blend;
        GLuint _blendSrcMode;
        GLuint _blendDstMode;
        GLuint _blendEquation;

        bool viewSource;

        std::vector<std::string> _output;
        uint8_t _outputTempModes[20];
        NCLGLPgrInValue in_vertex_values[100];
        NCLGLPgrInValue in_fragment_values[100];
        int _v_inValuesCount;
        int _f_inValuesCount;

        bool _vertexP_ready;
        bool _fragmentP_ready;

        std::string _vertexHead;
        std::string _vertexSource;
        std::string _fragmentHead;
        std::string _fragmentSource;

        GLuint pgr_vertexFragment;
        GLint uOffset;
        GLint uBufferWidth;

        uint8_t _drawMode;

        GLuint getEnumBlendMode(std::string *blendStr);
        std::string lines_header(NCLGLPgrInValue in_values[], int *count);
        std::string get_global_id3_GLSLFunctionString();
        std::string get_global_id2_GLSLFunctionString();
        std::string lines_drawBuffersWriteInit_GL2();
        std::string lines_drawBuffersInit();
        std::string lines_drawBuffersWrite_GL2();
        void compile();
        void setVertexSource(std::string header, std::string source, std::vector<std::string> varname, std::vector<std::string> varnameC, std::vector<std::string> type, std::vector<std::string> expectedMode);
        void setFragmentSource(std::string header, std::string source, std::vector<std::string> varname, std::vector<std::string> varnameC, std::vector<std::string> type, std::vector<std::string> expectedMode);

    private:
        int dd;
};

#endif //NCLGL_NCLGLVERTEXFRAGMENTPROGRAM_H